import { CentralAuthClass } from "centralauth/server";
import { headers } from "next/headers";
import { NextResponse } from "next/server";

// CentralAuth centralized authentication endpoints (quick-example, steps 6-9):
//   /api/auth/login    -> redirect to the CentralAuth hosted login page
//   /api/auth/callback -> finish the OAuth-style flow, set the session cookie
//   /api/auth/user     -> current session user (or null)
//   /api/auth/logout   -> end the session
export async function GET(
  req: Request,
  props: { params: Promise<{ action: string }> }
) {
  const { action } = await props.params;
  const headerList = await headers();

  const requestUrl = new URL(req.url);
  const authClient = new CentralAuthClass({
    clientId: process.env.AUTH_ORGANIZATION_ID,
    secret: process.env.AUTH_SECRET,
    authBaseUrl: process.env.AUTH_BASE_URL,
    callbackUrl: `${requestUrl.origin}/api/auth/callback`,
  });

  try {
    if (action == "login") return await authClient.login(req);
    if (action == "callback") return await authClient.callback(req);
    if (action == "user") return await authClient.user(headerList);
    if (action == "logout") return await authClient.logout(req);
  } catch (error: unknown) {
    console.log(error);
    const message =
      error instanceof Error ? error.message : "Authentication error";
    if (action == "callback") {
      // Show the failure on the landing page instead of a raw 500.
      return NextResponse.redirect(
        new URL(`/?auth_error=${encodeURIComponent(message)}`, requestUrl.origin)
      );
    }
    return NextResponse.json({ error: message }, { status: 502 });
  }
}
